-- | Module lists in the .cabal files.
module DomGen.Emit.Cabal
  ( spliceJSaddleDomCabal
  , spliceGhcjsDomJSaddleCabal
  , ghcjsDomJSaddleReexports
  , spliceGhcjsDomCabal
  , spliceGhcjsDomJavaScriptCabal
  , ghcjsDomJavaScriptReexports
  ) where

import qualified Data.Set as S
import Data.Text (Text)
import qualified Data.Text as T

-- | Replace the library's module lists (from @exposed-modules:@ up to the
-- library @build-depends:@) of jsaddle-dom.cabal.
--
-- @spliceJSaddleDomCabal custom generated src@ where @custom@ are the
-- hand written @JSDOM.Custom.*@ modules and @generated@ the
-- @JSDOM.Generated.*@ module suffixes.
spliceJSaddleDomCabal :: [Text] -> [Text] -> Text -> Either String Text
spliceJSaddleDomCabal custom generated src =
  case break (== "    exposed-modules:") ls of
    (before, _ : rest) -> case break (== "    build-depends:") rest of
      (_, after@(_ : _)) -> Right (T.unlines (before <> modules <> after))
      _ -> Left "jsaddle-dom.cabal: no library build-depends after exposed-modules"
    _ -> Left "jsaddle-dom.cabal: no exposed-modules in library"
  where
    ls = T.lines src
    customSet = S.fromList custom
    handWritten = ["JSDOM", "JSDOM.EventM", "JSDOM.Types", "JSDOM.Enums", "JSDOM.EventTargetClosures"]
    modules =
      [ "    exposed-modules:"
      , "        -- The module lists below are generated by dom-gen; do not edit."
      ] <> map ("        " <>) (handWritten <> map ("JSDOM.Custom." <>) custom <> map ("JSDOM.Generated." <>) generated)
      <> [ "    reexported-modules:" ]
      <> commaSep
           ( [ "JSDOM.Custom." <> c <> " as JSDOM." <> c | c <- custom ]
          <> [ "JSDOM.Generated." <> g <> " as JSDOM." <> g | g <- generated, g /= "Enums", not (S.member g customSet) ] )
    commaSep xs = zipWith (\i x -> "        " <> x <> (if i < length xs then "," else "")) [(1 :: Int) ..] xs

-- | Replace everything from the library's @reexported-modules:@ line to the
-- end of the file (both ghcjs-dom cabal files end with that list).
spliceToEnd :: String -> [Text] -> Text -> Either String Text
spliceToEnd file new src = case break ("    reexported-modules:" `T.isPrefixOf`) (T.lines src) of
  (before, _ : _) -> Right (T.unlines (before <> new))
  _ -> Left (file <> ": no reexported-modules")

-- | The @JSDOM.X as GHCJS.DOM.X@ lines for the public jsaddle-dom modules
-- (also written to ghcjs-dom-jsaddle/reexported-modules.txt).
ghcjsDomJSaddleReexports :: [Text] -> Text
ghcjsDomJSaddleReexports public =
  T.unlines [ "          , JSDOM." <> m <> " as GHCJS.DOM." <> m | m <- public ]

-- | ghcjs-dom-jsaddle.cabal; @public@ are the @JSDOM.X@ module suffixes.
spliceGhcjsDomJSaddleCabal :: [Text] -> Text -> Either String Text
spliceGhcjsDomJSaddleCabal public = spliceToEnd "ghcjs-dom-jsaddle.cabal" $
  [ "    reexported-modules:"
  , "            JSDOM as GHCJS.DOM"
  , "          , JSDOM.Types as GHCJS.DOM.Types"
  , "          , JSDOM.EventM as GHCJS.DOM.EventM"
  , "          , JSDOM.EventTargetClosures as GHCJS.DOM.EventTargetClosures"
  , "          -- The list below is generated by dom-gen; do not edit."
  ] <> T.lines (ghcjsDomJSaddleReexports public)

-- | ghcjs-dom.cabal re-exports every backend module by name, except
-- GHCJS.DOM.Document, which it wraps (src/GHCJS/DOM/Document.hs).
spliceGhcjsDomCabal :: [Text] -> Text -> Either String Text
spliceGhcjsDomCabal public = spliceToEnd "ghcjs-dom.cabal" $
  [ "    reexported-modules: GHCJS.DOM,"
  , "                        GHCJS.DOM.Types,"
  , "                        GHCJS.DOM.EventM,"
  , "                        GHCJS.DOM.EventTargetClosures,"
  , "    -- The list below is generated by dom-gen; do not edit."
  ] <> zipWith (\i m -> "                        GHCJS.DOM." <> m <> (if i < length ms then "," else "")) [(1 :: Int) ..] ms
  where ms = filter (/= "Document") public

-- | ghcjs-dom-javascript.cabal: everything from the library's
-- @exposed-modules:@ to the end of the file (its last field is
-- @reexported-modules@).  @custom@ are the hand written
-- @GHCJS.DOM.JSFFI.*@ modules, @generated@ the
-- @GHCJS.DOM.JSFFI.Generated.*@ module suffixes.
spliceGhcjsDomJavaScriptCabal :: [Text] -> [Text] -> Text -> Either String Text
spliceGhcjsDomJavaScriptCabal custom generated src =
  case break (== "    exposed-modules:") (T.lines src) of
    (before, _ : _) -> Right (T.unlines (before <> modules))
    _ -> Left "ghcjs-dom-javascript.cabal: no exposed-modules in library"
  where
    handWritten = ["GHCJS.DOM", "GHCJS.DOM.Types", "GHCJS.DOM.EventM", "GHCJS.DOM.EventTargetClosures", "GHCJS.DOM.Internal"]
    modules =
      [ "    exposed-modules:"
      , "          -- The module lists below are generated by dom-gen; do not edit."
      ] <> map ("          " <>) (handWritten <> map ("GHCJS.DOM.JSFFI." <>) custom <> map ("GHCJS.DOM.JSFFI.Generated." <>) generated)
      <> [ "" , "    reexported-modules:" ]
      <> T.lines (ghcjsDomJavaScriptReexports custom generated)

-- | The @reexported-modules@ entries of ghcjs-dom-javascript (also written
-- to its reexported-modules.txt): custom modules replace generated ones.
ghcjsDomJavaScriptReexports :: [Text] -> [Text] -> Text
ghcjsDomJavaScriptReexports custom generated =
  T.unlines $ zipWith (\i l -> (if i == (0 :: Int) then "            " else "          , ") <> l) [0 ..] $
    [ "GHCJS.DOM.JSFFI." <> c <> " as GHCJS.DOM." <> c | c <- custom ]
    <> [ "GHCJS.DOM.JSFFI.Generated." <> g <> " as GHCJS.DOM." <> g
       | g <- generated, g /= "Enums", not (S.member g (S.fromList custom)) ]
    <> [ "GHCJS.DOM.JSFFI.Generated.Enums as GHCJS.DOM.Enums" ]
